def complexity(seq, k):
    blocks = set()
    for i in range(len(seq) - k + 1):
        blocks.add(tuple(seq[i:i+k]))
    return len(blocks)

# Example: Thue-Morse sequence
def thue_morse(n):
    seq = [0]
    while len(seq) < n:
        seq += [1 - x for x in seq]
    return seq[:n]

tm = thue_morse(100)
for k in range(1, 10):
    print(f"k={k}, p(k)={complexity(tm, k)}")

# Example: Sturmian-like sequence
def sturmian_like(n):
    # Using a simple irrational rotation to generate a Sturmian sequence
    # a_n = floor((n+1) * alpha) - floor(n * alpha)
    alpha = (5**0.5 - 1) / 2
    return [int(((i+1)*alpha) % 1 > ((i)*alpha) % 1) for i in range(n)]

st = sturmian_like(100)
for k in range(1, 10):
    print(f"k={k}, p(k)={complexity(st, k)}")
